style:
/* Artefatos exclusivos do Meaple: tokens do site, layouts pontuais ainda não reutilizados em outro lugar. */

.cs-note {
  border: 1px solid var(--b1);
  border-radius: 8px;
  padding: var(--sp-5) var(--sp-6);
  background: var(--bg1);
  display: flex;
  flex-direction: column;
  gap: var(--sp-2);
}
.cs-note__label {
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--y);
}
.cs-note p { font-size: var(--text-base); line-height: 1.65; color: var(--t2); }

.persona-timeline { list-style: none; display: grid; gap: 6px; margin: var(--sp-3) 0; }
.persona-timeline li { font-size: 13px; color: var(--t3); padding-left: 14px; position: relative; line-height: 1.4; }
.persona-timeline li::before { content: ""; position: absolute; left: 0; top: 7px; width: 4px; height: 4px; border-radius: 50%; background: var(--b1); }

.cmatrix { width: 100%; border-collapse: collapse; font-size: 13.5px; }
.cmatrix th, .cmatrix td { text-align: center; padding: 0; }
.cmatrix thead th {
  font-family: var(--mono); font-size: 10.5px; letter-spacing: .05em; text-transform: uppercase;
  color: var(--t3); padding: 0 6px 14px; vertical-align: bottom; line-height: 1.25;
}
.cmatrix thead th:first-child { text-align: left; }
.cmatrix tbody th {
  text-align: left; font-family: var(--sans); font-weight: 520; color: var(--t1); white-space: nowrap;
  padding: 9px 16px 9px 4px; border-top: 1px solid var(--b0);
}
.cmatrix tbody td { border-top: 1px solid var(--b0); height: 44px; }
.cmatrix .dot { width: 14px; height: 14px; border-radius: 50%; display: inline-block; background: var(--bg2); box-shadow: inset 0 0 0 1px var(--b1); }
.cmatrix .dot.on { background: var(--y); box-shadow: 0 0 0 1px var(--y); }
.cmatrix tr.meaple th, .cmatrix tr.meaple td { border-top: 1.5px solid var(--y); background: rgba(243,176,46,.06); }
.cmatrix tr.meaple th { color: var(--y); font-weight: 700; font-family: var(--display); text-transform: uppercase; letter-spacing: .01em; }
@media (max-width: 560px) {
  .cmatrix { font-size: 11.5px; }
  .cmatrix thead th { font-size: 9px; padding: 0 2px 10px; }
  .cmatrix tbody th { white-space: normal; font-size: 11.5px; padding: 8px 6px 8px 2px; line-height: 1.15; }
  .cmatrix tbody td { height: 36px; }
}

.scatter { position: relative; width: 100%; aspect-ratio: 1.35/1; max-width: 620px; margin-inline: auto; }
.scatter svg { width: 100%; height: 100%; overflow: visible; }
.sc-lab { font-family: var(--mono); font-size: 9px; fill: var(--t2); letter-spacing: .02em; }
.sc-axis { font-family: var(--mono); font-size: 10px; fill: var(--t3); letter-spacing: .1em; text-transform: uppercase; }
.scatter-legend { display: flex; flex-wrap: wrap; gap: var(--sp-4); margin-top: var(--sp-5); font-family: var(--mono); font-size: 11px; color: var(--t2); }
.scatter-legend span { display: flex; align-items: center; gap: 8px; }
.scatter-legend i { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.scatter-legend i.imp { background: var(--y); }
.scatter-legend i.override { background: #f87171; }
.scatter-legend i.base { background: var(--t2); }
.sc-lab { font-weight: 700; }

.targets-grid { display: grid; grid-template-columns: 1fr; gap: 1px; background: var(--b0); border: 1px solid var(--b0); border-radius: 8px; overflow: hidden; }
@media (min-width: 480px) { .targets-grid { grid-template-columns: repeat(2, 1fr); } }

.tier-relations { border: 1px dashed var(--b1); border-radius: 8px; padding: var(--sp-5); margin-top: var(--sp-5); }
.tier-relations__label { font-family: var(--mono); font-size: 10.5px; letter-spacing: .14em; text-transform: uppercase; color: var(--t3); margin-bottom: var(--sp-3); }
.tier-relations ul { list-style: none; display: grid; gap: 8px; }
.tier-relations li { font-size: 13.5px; color: var(--t2); padding-left: 20px; position: relative; }
.tier-relations li::before { content: "→"; position: absolute; left: 0; color: var(--y); }
.tier-relations b { color: var(--t1); }

.momentum { display: grid; grid-template-columns: 1.3fr auto .9fr; gap: var(--sp-6); align-items: center; }
@media (max-width: 760px) { .momentum { grid-template-columns: 1fr; gap: var(--sp-4); } }
.mo-inputs { display: grid; gap: 8px; }
.mo-in { border: 1px solid var(--b0); border-radius: 8px; padding: 12px 16px; background: var(--bg1); font-size: 13.5px; display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.mo-in .sub { font-family: var(--mono); font-size: 10.5px; color: var(--t3); text-align: right; }
.mo-in.key { border-color: var(--y); background: rgba(243,176,46,.08); }
.mo-in.key .nm { color: var(--y); font-weight: 600; }
.mo-arrow { font-family: var(--mono); color: var(--y); font-size: 20px; text-align: center; }
@media (max-width: 760px) { .mo-arrow { transform: rotate(90deg); } }
.mo-out { border: 1px solid var(--y); border-radius: 8px; padding: var(--sp-6); background: rgba(243,176,46,.06); text-align: center; }
.mo-out .ot { font-family: var(--display); font-size: 20px; text-transform: uppercase; color: var(--t1); }
.mo-out .os { font-size: 12.5px; color: var(--t2); margin-top: 10px; line-height: 1.45; }

.scope-group { margin-bottom: var(--sp-4); }
.scope-group__label { font-family: var(--mono); font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--t3); margin-bottom: 8px; }
.scope-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.scope-chip { font-size: 12px; border: 1px solid var(--b1); border-radius: 100px; padding: 4px 11px; color: var(--t2); background: var(--bg); }
.scope-chip.against { border-color: var(--y); color: var(--y); background: rgba(243,176,46,.08); }
.scope-chip .why { font-family: var(--mono); font-size: 9.5px; opacity: .7; margin-left: 6px; }

.roadmap { display: grid; grid-template-columns: 1fr; gap: var(--sp-3); }
@media (min-width: 560px) { .roadmap { grid-template-columns: repeat(2, 1fr); } }
.roadmap-month { border: 1px solid var(--b0); border-radius: 8px; background: var(--bg1); overflow: hidden; }
.roadmap-month__head { font-family: var(--display); font-size: 15px; text-transform: uppercase; padding: 12px 14px; border-bottom: 1px solid var(--b0); display: flex; justify-content: space-between; align-items: center; color: var(--t1); }
.roadmap-month__head span { font-family: var(--mono); font-size: 10px; color: var(--y); text-transform: none; }
.roadmap-month ul { list-style: none; padding: 10px 14px; display: grid; gap: 6px; }
.roadmap-month li { font-size: 12px; color: var(--t3); line-height: 1.3; padding-left: 12px; position: relative; }
.roadmap-month li::before { content: ""; position: absolute; left: 0; top: 7px; width: 4px; height: 4px; border-radius: 50%; background: var(--y); }

.ctx-grid { display: grid; grid-template-columns: 1fr; gap: var(--sp-3); }
@media (min-width: 560px) { .ctx-grid { grid-template-columns: repeat(2, 1fr); } }
.ctx-card { border: 1px solid var(--b0); border-radius: 8px; padding: var(--sp-4); background: var(--bg1); }
.ctx-card .ci { margin-bottom: 12px; height: 24px; }
.ctx-card .ci svg { width: 22px; height: 22px; stroke: var(--y); stroke-width: 1.6; fill: none; stroke-linecap: round; stroke-linejoin: round; }
.ctx-card h4 { font-family: var(--display); font-size: 15px; text-transform: uppercase; margin-bottom: 6px; color: var(--t1); }
.ctx-card p { font-size: 12.5px; color: var(--t2); line-height: 1.45; margin: 0; }

.ladder { display: grid; gap: 6px; max-width: 560px; }
.rung { display: flex; align-items: center; gap: 14px; border: 1px solid var(--b0); border-radius: 8px; padding: 11px 16px; background: var(--bg1); }
.rung .rk { font-family: var(--mono); font-size: 12px; color: var(--y); width: 20px; }
.rung .rn { font-family: var(--display); font-size: 15px; text-transform: uppercase; color: var(--t1); }
.rung .rv { margin-left: auto; font-family: var(--mono); font-size: 11px; color: var(--t3); }
.rung:first-child { border-color: var(--y); background: rgba(243,176,46,.06); }
.chain { margin-top: var(--sp-5); display: flex; flex-wrap: wrap; align-items: center; gap: 10px; font-family: var(--mono); font-size: 12px; color: var(--t2); }
.chain .step { border: 1px solid var(--b1); border-radius: 100px; padding: 6px 13px; }
.chain .arr { color: var(--y); }

.brand-logos { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--sp-4); margin-bottom: var(--sp-6); }
@media (max-width: 620px) { .brand-logos { grid-template-columns: 1fr; } }
.brand-logo-cell { border-radius: 8px; padding: 32px 20px; display: flex; flex-direction: column; align-items: center; gap: 14px; }
.brand-logo-cell img { height: 46px; width: auto; }
.brand-logo-cell.light { background: #ededf1; }
.brand-logo-cell.dark { background: #1C1C38; }
.brand-logo-cell .lname { font-family: var(--sans); font-weight: 700; font-size: 20px; }
.brand-logo-cell.light .lname { color: #1C1C38; }
.brand-logo-cell.dark .lname { color: #fff; }
.brand-pal { display: flex; flex-wrap: wrap; gap: var(--sp-8); }
.brand-pal-group__label { font-family: var(--mono); font-size: 11px; letter-spacing: .14em; text-transform: uppercase; color: var(--t3); margin-bottom: var(--sp-3); }
.brand-swatches { display: flex; gap: var(--sp-3); flex-wrap: wrap; }
.brand-swatches span { display: flex; flex-direction: column; align-items: center; gap: 8px; }
.brand-swatches i { width: 42px; height: 42px; border-radius: 50%; display: block; box-shadow: 0 0 0 1px var(--b1); }
.brand-swatches em { font-family: var(--mono); font-size: 10px; color: var(--t2); font-style: normal; }
.brand-swatches i.c-cyan   { background: #00C0FD; }
.brand-swatches i.c-blue   { background: #007CFF; }
.brand-swatches i.c-violet { background: #5500FA; }
.brand-swatches i.c-deep   { background: #310097; }
.brand-swatches i.c-white  { background: #FFFFFF; }
.brand-swatches i.c-navy   { background: #1C1C38; }

.u-mt-lead { margin-bottom: var(--sp-8); }
.u-title-tight { margin: .3em 0 .6em; }
.outcome-section { border-top: 1px solid var(--b0); padding-block: var(--sp-16); }
.outcome-title { margin: .2em 0 .5em; }
.outcome-trust { margin: var(--sp-6) 0; }
.outcome-quote { margin-bottom: var(--sp-8); }
.outcome-sources { max-width: 70ch; }
.outcome-body { max-width: 64ch; }

.cs-section__body ul.plain { list-style: none; display: grid; gap: 6px; margin: 0; }
.cs-section__body ul.plain li { font-size: var(--text-base); line-height: 1.6; color: var(--t2); padding-left: 16px; position: relative; }
.cs-section__body ul.plain li::before { content: ""; position: absolute; left: 0; top: 10px; width: 4px; height: 4px; border-radius: 50%; background: var(--y); }

.gallery-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: var(--sp-5); }
.gallery-thumb { border: none; background: none; padding: 0; cursor: pointer; display: flex; flex-direction: column; gap: 10px; text-align: center; font: inherit; }
.gallery-thumb img { width: 100%; height: auto; border-radius: 16px; background: #0d0d18; box-shadow: 0 0 0 1px var(--b1); transition: transform .2s; }
.gallery-thumb:hover img, .gallery-thumb:focus-visible img { transform: translateY(-4px); }
.gallery-thumb span { font-family: var(--mono); font-size: 11px; color: var(--t3); }
.cs-lightbox--gallery img { border-radius: 24px; }
